// 13. a stage with no row and inputs ready → materialize_stage followed by one materialize_unit per driver artifact.

test("case 13: a stage with no row materializes once per driver artifact, in artifact order", () => {
  const definition = fanOutDefinition({ stage_key: "build", over_input: "brief" });
  const versioningBrief = availableBrief("versioning", []);
  const schemaBrief = availableBrief("schema", []);
  const snap = snapshot({ definition, available_artifacts: [versioningBrief, schemaBrief] });

  const result = derive(snap);
  expect(result.ok).toBe(true);
  if (!result.ok) return;
  expect(result.value.commands.map((command) => command.kind)).toEqual(["materialize_stage", "materialize_unit", "materialize_unit"]);
  const minted = result.value.commands.filter((command): command is Extract<Command, { kind: "materialize_unit" }> => command.kind === "materialize_unit");
  expect(minted.map((command) => command.unit_id)).toEqual(["versioning" as UnitId, "schema" as UnitId]);
});

// -----------------------------------------------------------------------
// 14. stage closed and every unit satisfied → mark_stage_succeeded.

test("case 14: a closed stage whose units are all satisfied succeeds", () => {
  const snap = snapshot({
    definition: emptyDefinition(),
    stages: [stage({ stage_key: "build", materialization_closed: true, units: [unit({ stage_key: "build", unit_id: "u", state: "satisfied", required_slots: [releasedSlot()] })] })],
  });
  expect(derive(snap)).toEqual({ ok: true, value: { commands: [{ kind: "mark_stage_succeeded", stage_instance_id: snap.stages[0]!.id }] } });
});

// -----------------------------------------------------------------------
// 15. every definition stage stored with state succeeded → complete_run(succeeded).

test("case 15: every definition stage stored as succeeded completes the run", () => {
  const definition = scalarStageDefinition(["a", "b"]);
  const snap = snapshot({
    definition,
    stages: [
      stage({ stage_key: "a", state: "succeeded", materialization_closed: true, units: [] }),
      stage({ stage_key: "b", state: "succeeded", materialization_closed: true, units: [] }),
    ],
  });
  expect(derive(snap)).toEqual({ ok: true, value: { commands: [{ kind: "complete_run", outcome: { kind: "succeeded" } }] } });
});

// -----------------------------------------------------------------------
// 16. a stored stage already succeeded gets no mark_stage_succeeded again.

test("case 16: an already-succeeded stage is never re-marked succeeded", () => {
  const definition = scalarStageDefinition(["build"]);
  const snap = snapshot({
    definition,
    stages: [stage({ stage_key: "build", state: "succeeded", materialization_closed: true, units: [unit({ stage_key: "build", unit_id: "u", state: "satisfied", required_slots: [releasedSlot()] })] })],
  });
  expect(derive(snap)).toEqual({ ok: true, value: { commands: [{ kind: "complete_run", outcome: { kind: "succeeded" } }] } });
});

/**
 * A small builder so each `derive` test case reads as facts, not fixtures.
 * Every id is derived deterministically from `RUN_ID` via `src/decision/ids`,
 * exactly as production would compute it.
 */
import { createHash } from "node:crypto";

import type { CompiledStageContract, CompiledWorkflowDefinition } from "../../src/domain/compiled-workflow";
import { fingerprintOf, runUnitIdFor, stageInstanceIdFor } from "../../src/decision/ids";
import type { AvailableArtifact, RunSnapshot, StagePolicy, StageSnapshot, UnitSnapshot } from "../../src/decision/snapshot";
import type { ArtifactId, InputFingerprint, JsonValue, OutputSlotVersion, RunRecordVersion, RunUnitId, StageInstanceId, UnitId, WaitId, WorkflowDefinitionId, WorkflowRunId, WorkOrderId } from "../../src/domain/primitives";
import type { RunOutputSlot, RunStage, UnitState, WorkflowRun, WorkOrder } from "../../src/domain/run-record";
import type { Wait } from "../../src/domain/wait";
import type { StageKey, StageOutcome } from "../../src/domain/workflow";

/** Deterministic fixture-id generator, local to this builder — same shape as (but independent of) `src/decision/ids.ts`'s internal `stableUuid`; determinism matters for case 12 (derive is stable across repeated calls). */
const localStableUuid = (identity: string): string => {
  const hex = createHash("sha256").update(identity).digest("hex").slice(0, 32);
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-4${hex.slice(13, 16)}-8${hex.slice(17, 20)}-${hex.slice(20)}`;
};

export const RUN_ID = "11111111-1111-4111-8111-111111111111" as WorkflowRunId;
export const NOW = "2026-08-29T12:00:00.000Z";
export const PRODUCER_STAGE_KEY = "brief_writer" as StageKey;
export const PRODUCER_OUTPUT_NAME = "brief";

const definitionId = "66666666-6666-4666-8666-666666666666" as WorkflowDefinitionId;

export const run = (options?: { readonly context?: JsonValue; readonly state?: WorkflowRun["state"]; readonly outcome?: StageOutcome | null; readonly record_version?: number }): WorkflowRun => ({
  id: RUN_ID, workflow_definition_id: definitionId, workflow_definition_version: 1,
  context: options?.context ?? {}, state: options?.state ?? "active", outcome: options?.outcome ?? null,
  record_version: (options?.record_version ?? 1) as RunRecordVersion, created_at: NOW, ended_at: null,
});

export const emptyDefinition = (): CompiledWorkflowDefinition => ({ stages: {}, edges: [], source_stages: [] });

/** One stage per key, `scalar` materialization — enough for run-completion (§D) tests that only care about stage membership. */
export const scalarStageDefinition = (stage_keys: readonly string[]): CompiledWorkflowDefinition => ({
  stages: Object.fromEntries(stage_keys.map((key): [string, CompiledStageContract] => [key, {
    stage_key: key as StageKey, stage_type: "delegated_session", operator_role: null, inputs: [], outputs: [],
    materialization: { kind: "scalar" }, executor: { executor_type: "delegated_session", definition_config: {} },
  }])),
  edges: [], source_stages: stage_keys as StageKey[],
});

/**
 * A fan-out consumer at `stage_key`, driven over a `unit_complete` edge from a
 * `brief_writer` producer — the dev-flow `build` shape spec §4 describes. The
 * driver item shape is `{ unit_id: artifact.unit_id, artifact: artifact.body }`
 * (`resolveBindingValue`'s `inputBindingValue`), so `unit_id_path` is `/unit_id`
 * and `depends_on_path` is `/artifact/depends_on`.
 *
 * `brief_writer` is deliberately NOT a key of `definition.stages`: `derive`'s
 * materialization loop (§B) only visits definition stages, and every
 * producer-side fact it needs — readiness, closure — comes from
 * `available_artifacts` and an optional `StageSnapshot` row, both independent
 * of the definition. A test that wants `brief_writer` "finished" stores that
 * row directly (`stage({ stage_key: PRODUCER_STAGE_KEY, materialization_closed: true, units: [...] })`);
 * one that wants the collection "open" simply never stores it.
 */
export const fanOutDefinition = (options: { readonly stage_key: string; readonly over_input: string; readonly max_parallel?: number; readonly manual_admission?: boolean }): CompiledWorkflowDefinition => {
  const consumer: CompiledStageContract = {
    stage_key: options.stage_key as StageKey, stage_type: "delegated_session", operator_role: "build",
    inputs: [{ name: options.over_input, artifact_type: "dev.brief", optional: false, collect: true, delivery: "unit_complete" }],
    outputs: [{ name: "result", artifact_type: "dev.build_result", release: { kind: "immediate" } }],
    materialization: { kind: "fan_out", over: { from: "input", input_name: options.over_input }, unit_id_path: "/unit_id", depends_on_path: "/artifact/depends_on",
      max_parallel: options.max_parallel ?? 1, manual_admission: options.manual_admission ?? false },
    executor: { executor_type: "delegated_session", definition_config: {} },
  };
  return {
    stages: { [options.stage_key]: consumer },
    edges: [{ producer_stage: PRODUCER_STAGE_KEY, producer_output: PRODUCER_OUTPUT_NAME, consumer_stage: options.stage_key as StageKey, consumer_input: options.over_input, delivery: "unit_complete" }],
    source_stages: [],
  };
};

/** The `run_unit_id` `derive` computes for `(stage_key, unit_id)` — the same one `unit()` gives that unit's `id`. */
export const runUnitIdForTest = (stage_key: string, unit_id: string): RunUnitId => runUnitIdFor(RUN_ID, stage_key as StageKey, unit_id as UnitId);

export const stage = (options: {
  readonly stage_key: string; readonly state?: RunStage["state"]; readonly materialization_closed?: boolean;
  readonly max_parallel?: number; readonly manual_admission?: boolean; readonly units?: readonly UnitSnapshot[];
}): StageSnapshot => ({
  id: stageInstanceIdFor(RUN_ID, options.stage_key as StageKey), stage_key: options.stage_key as StageKey,
  state: options.state ?? "active", materialization_closed: options.materialization_closed ?? false,
  policy: { max_parallel: options.max_parallel ?? 1, manual_admission: options.manual_admission ?? false } satisfies StagePolicy,
  units: options.units ?? [],
});

export const unit = (options: {
  readonly stage_key: string; readonly unit_id: string; readonly state?: UnitState; readonly admitted?: boolean;
  readonly outcome?: StageOutcome | null; readonly depends_on?: readonly string[]; readonly parameters?: JsonValue;
  readonly input_fingerprint?: string; readonly required_slots?: readonly RunOutputSlot[]; readonly open_waits?: readonly Wait[];
  readonly work_orders?: readonly WorkOrder[];
}): UnitSnapshot => ({
  id: runUnitIdFor(RUN_ID, options.stage_key as StageKey, options.unit_id as UnitId),
  unit_id: options.unit_id as UnitId, parameters: options.parameters ?? {},
  input_fingerprint: (options.input_fingerprint ?? "fingerprint") as InputFingerprint,
  state: options.state ?? "ready", admitted: options.admitted ?? true, outcome: options.outcome ?? null,
  depends_on: (options.depends_on ?? []) as UnitId[],
  // Defaults to one un-released slot: a real unit always carries at least one output, and an
  // empty array would trivially satisfy `.every(released)` and mis-fire `mark_unit_satisfied`.
  required_slots: options.required_slots ?? [emptySlot()],
  open_waits: options.open_waits ?? [], work_orders: options.work_orders ?? [],
});

/** A brief artifact from `brief_writer`, driving a fan-out unit named `unit_id` with the given dependencies. */
export const availableBrief = (unit_id: string, depends_on: readonly string[], artifact_id?: string, body?: JsonValue): AvailableArtifact => ({
  artifact_id: (artifact_id ?? localStableUuid(`brief:${unit_id}`)) as ArtifactId, artifact_type: "dev.brief", output_name: PRODUCER_OUTPUT_NAME,
  unit_id: unit_id as UnitId, body: body ?? ({ depends_on } as JsonValue), producer_stage_key: PRODUCER_STAGE_KEY,
});

/**
 * The `input_fingerprint` `derive` will compute for a unit driven solely by
 * `brief` — matches production exactly (`fingerprintOf(envelopes(unitInputs))`
 * where `unitInputs.brief` is filtered down to the one matching artifact).
 * Set a stored `unit()`'s `input_fingerprint` to this to prove "no revision".
 */
export const fingerprintForBrief = (brief: AvailableArtifact): InputFingerprint => fingerprintOf([brief]);

let workOrderSeq = 0;
export const workOrder = (options: { readonly state: WorkOrder["state"]; readonly created_at?: string; readonly run_unit_id?: RunUnitId; readonly id?: string }): WorkOrder => {
  workOrderSeq += 1;
  const id = (options.id ?? localStableUuid(`work-order:${workOrderSeq}`)) as WorkOrderId;
  const created_at = options.created_at ?? NOW;
  return {
    id, run_unit_id: options.run_unit_id ?? (localStableUuid("placeholder-run-unit") as RunUnitId), reason: "initial",
    input_snapshot: [], input_fingerprint: "inputs" as InputFingerprint, state: options.state, workflow_id: `v2-work:${id}`,
    request_idempotency_key: "initial", created_at,
    completed_at: options.state === "completed" || options.state === "abandoned" ? created_at : null,
  };
};

const baseSlot = (state: RunOutputSlot["state"], options?: { readonly output_name?: string; readonly run_unit_id?: RunUnitId }): RunOutputSlot => ({
  run_unit_id: options?.run_unit_id ?? (localStableUuid("placeholder-run-unit") as RunUnitId),
  identity: { kind: "scalar", output_name: options?.output_name ?? "result" }, output_name: options?.output_name ?? "result",
  artifact_type: "dev.build_result", required: true, release: { kind: "immediate" }, state,
  updated_by_work_order_id: null, version: 1 as OutputSlotVersion,
});

export const releasedSlot = (options?: { readonly output_name?: string; readonly run_unit_id?: RunUnitId; readonly artifact_id?: string }): RunOutputSlot =>
  baseSlot({ kind: "released", artifact_revision_id: (options?.artifact_id ?? localStableUuid("released-slot")) as ArtifactId, released_at: NOW }, options);

export const emptySlot = (options?: { readonly output_name?: string; readonly run_unit_id?: RunUnitId }): RunOutputSlot => baseSlot({ kind: "empty" }, options);

let waitSeq = 0;
export const openWait = (options?: { readonly unit_id?: string; readonly stage_instance_id?: StageInstanceId }): Wait => {
  waitSeq += 1;
  return {
    id: localStableUuid(`wait:${waitSeq}`) as WaitId, stage_instance_id: options?.stage_instance_id ?? (localStableUuid("placeholder-stage") as StageInstanceId),
    unit_id: (options?.unit_id ?? "unit") as UnitId, artifact_revision_id: localStableUuid("wait-artifact") as ArtifactId,
    closes_on: { kind: "gate", gate_step: "artifact_approval", actions: ["approve"] }, status: { kind: "open" },
    run_unit_id: null, output_name: null, execution_workflow_id: "v2-work:placeholder", command_workflow_id: "v2-wait:placeholder", opened_at: NOW,
  };
};

export const snapshot = (options?: {
  readonly run?: WorkflowRun; readonly definition?: CompiledWorkflowDefinition; readonly stages?: readonly StageSnapshot[]; readonly available_artifacts?: readonly AvailableArtifact[];
}): RunSnapshot => ({
  run: options?.run ?? run(), definition: options?.definition ?? emptyDefinition(),
  stages: options?.stages ?? [], available_artifacts: options?.available_artifacts ?? [],
});

/**
 * What `derive` may say, and the three ways it can prove a run cannot
 * proceed. Amends spec §3.3 (final): `Command.materialize_stage` drops
 * `stage_contract` (the storage layer already holds the compiled definition
 * and can look the contract up by `stage_key`); `materialize_unit` /
 * `revise_unit` gain `stage_key` and `inputs` — the named per-unit input map
 * — because `apply` must resolve slot bindings by input name, and
 * `input_snapshot` alone (its flattened envelopes) cannot answer "what is
 * input 'brief'".
 *
 * `StageInputSet` moves here from `compiler/select-unit-inputs.ts`, which is
 * deleted in the same PR — do not import it.
 */
import type { ArtifactEnvelope } from "../domain/execution";
import type { ArtifactId, InputFingerprint, JsonValue, RunRecordVersion, RunUnitId, StageInstanceId, UnitId, WorkOrderId } from "../domain/primitives";
import type { MaterializedRunOutput } from "../domain/run-record";
import type { StageKey, StageOutcome } from "../domain/workflow";
import type { StagePolicy } from "./snapshot";

export type StageInputSet = Readonly<Record<string, ArtifactEnvelope | readonly ArtifactEnvelope[]>>;

export type Command =
  | { readonly kind: "materialize_stage"; readonly stage_key: StageKey; readonly stage_instance_id: StageInstanceId; readonly policy: StagePolicy }
  | {
      readonly kind: "materialize_unit";
      readonly stage_key: StageKey;
      readonly stage_instance_id: StageInstanceId;
      readonly run_unit_id: RunUnitId;
      readonly unit_id: UnitId;
      readonly parameters: JsonValue;
      readonly depends_on: readonly UnitId[];
      readonly inputs: StageInputSet;
      readonly input_snapshot: readonly ArtifactEnvelope[];
      readonly input_fingerprint: InputFingerprint;
      readonly outputs: readonly MaterializedRunOutput[];
      /** Part of the stage's stored materialization fingerprint; `apply` needs it to persist the unit. */
      readonly policy: StagePolicy;
    }
  | {
      readonly kind: "revise_unit";
      readonly stage_key: StageKey;
      readonly stage_instance_id: StageInstanceId;
      readonly run_unit_id: RunUnitId;
      readonly unit_id: UnitId;
      readonly parameters: JsonValue;
      readonly inputs: StageInputSet;
      readonly input_snapshot: readonly ArtifactEnvelope[];
      readonly input_fingerprint: InputFingerprint;
    }
  | { readonly kind: "close_materialization"; readonly stage_key: StageKey; readonly stage_instance_id: StageInstanceId; readonly policy: StagePolicy }
  | { readonly kind: "mark_unit_satisfied"; readonly run_unit_id: RunUnitId }
  | { readonly kind: "start_work"; readonly work_order_id: WorkOrderId; readonly run_unit_id: RunUnitId }
  | { readonly kind: "mark_stage_succeeded"; readonly stage_instance_id: StageInstanceId }
  | { readonly kind: "complete_run"; readonly outcome: StageOutcome };

export type Contradiction =
  | { readonly kind: "unknown_dependency_at_close"; readonly stage_key: StageKey; readonly unit_id: UnitId; readonly dependency: UnitId }
  | { readonly kind: "dependency_cycle"; readonly stage_key: StageKey; readonly cycle: readonly UnitId[] }
  /** `artifact_id` is null only when the fan-out drives over a non-input binding (repository provisioning fans out over run context). */
  | { readonly kind: "malformed_driver_artifact"; readonly stage_key: StageKey; readonly artifact_id: ArtifactId | null; readonly path: string; readonly detail: string };

export interface Derivation {
  /** One atomic batch, in application order; empty = nothing to do. */
  readonly commands: readonly Command[];
}

/** What `decide_run` (storage layer) returns to the root loop. Replaces `RunDecision`. */
export type AskResult =
  | { readonly kind: "complete"; readonly outcome: StageOutcome }
  | { readonly kind: "recheck"; readonly record_version: RunRecordVersion; readonly started: readonly { readonly id: WorkOrderId; readonly run_unit_id: RunUnitId }[] }
  | { readonly kind: "wait"; readonly record_version: RunRecordVersion };

/**
 * `derive` is the whole of spec §1 in one function: the only production
 * implementation of the run's eligibility rules. It reads a `RunSnapshot`
 * (persisted facts, loaded outside this file) and returns the commands
 * provable from it — never a fact it is itself about to write (the
 * "recheck contract", spec §3.3).
 *
 * Materialization rules are spec §4, moved verbatim from
 * `runtime/run-materialization.ts` (`stageInputs`, `stageFinished`,
 * `isReady`, `shouldClose`, `selectInputsForUnit`, `outputSlots`,
 * `envelopes`) and `compiler/materialize-units.ts` (`parseUnit`,
 * `selectDriverArtifacts`, the cycle DFS in `appendIncrementalUnit`).
 */
import type { CompiledStageContract, CompiledWorkflowDefinition, MaterializedExecutionUnit } from "../domain/compiled-workflow";
import type { SlotBinding } from "../domain/delegated-session";
import type { ArtifactEnvelope } from "../domain/execution";
import { err, ok, type ArtifactId, type InputFingerprint, type JsonValue, type OutputCollectionKey, type Result, type RunUnitId, type StageInstanceId, type UnitId, type WorkflowRunId } from "../domain/primitives";
import type { MaterializedRunOutput } from "../domain/run-record";
import type { StageKey, StageOutcome } from "../domain/workflow";
import { resolveBindingValue, type BindingEnvironment } from "../compiler/resolve-execution";
import { readJsonPointer } from "../domain/json-pointer";
import type { Command, Contradiction, Derivation, StageInputSet } from "./commands";
import { fingerprintOf, runUnitIdFor, stageInstanceIdFor } from "./ids";
import type { RunSnapshot, StagePolicy, StageSnapshot, UnitSnapshot } from "./snapshot";

const TERMINAL_UNIT_STATES = new Set<UnitSnapshot["state"]>(["satisfied", "failed", "cancelled"]);

const byString = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

// ---------------------------------------------------------------------------
// A. Child outcome facts

const findFirstUnit = (snapshot: RunSnapshot, predicate: (unit: UnitSnapshot) => boolean): UnitSnapshot | null => {
  for (const stage of [...snapshot.stages].sort((a, b) => byString(a.stage_key, b.stage_key))) {
    for (const unit of [...stage.units].sort((a, b) => byString(a.unit_id, b.unit_id))) if (predicate(unit)) return unit;
  }
  return null;
};

// ---------------------------------------------------------------------------
// B. Materialization — moved verbatim from runtime/run-materialization.ts

const envelopes = (inputs: StageInputSet): readonly ArtifactEnvelope[] =>
  Object.values(inputs).flatMap((value) => (Array.isArray(value) ? value : [value as ArtifactEnvelope]));

const stageInputs = (stage_key: StageKey, definition: CompiledWorkflowDefinition, snapshot: RunSnapshot): StageInputSet => {
  const result: Record<string, ArtifactEnvelope | readonly ArtifactEnvelope[]> = {};
  const stage = definition.stages[stage_key];
  if (!stage) return result;
  for (const edge of definition.edges.filter((candidate) => candidate.consumer_stage === stage_key)) {
    const values = snapshot.available_artifacts.filter((artifact) => artifact.producer_stage_key === edge.producer_stage && artifact.output_name === edge.producer_output);
    const input = stage.inputs.find((candidate) => candidate.name === edge.consumer_input);
    const driver = stage.materialization.kind !== "scalar" && stage.materialization.kind !== "artifact_collection"
      && stage.materialization.over.from === "input" && stage.materialization.over.input_name === edge.consumer_input;
    if (edge.delivery === "unit_complete" || input?.collect === true || driver) result[edge.consumer_input] = values;
    else if (values[0]) result[edge.consumer_input] = values[0];
  }
  return result;
};

const stageFinished = (snapshot: RunSnapshot, stage_key: StageKey): boolean => {
  const stage = snapshot.stages.find((candidate) => candidate.stage_key === stage_key);
  return Boolean(stage?.materialization_closed && stage.units.every((unit) => unit.state === "satisfied"));
};

const isReady = (stage_key: StageKey, definition: CompiledWorkflowDefinition, snapshot: RunSnapshot): boolean => {
  const stage = definition.stages[stage_key];
  if (!stage) return false;
  for (const input of stage.inputs.filter((candidate) => !candidate.optional)) {
    const edge = definition.edges.find((candidate) => candidate.consumer_stage === stage_key && candidate.consumer_input === input.name);
    if (!edge) return false;
    const available = snapshot.available_artifacts.some((artifact) => artifact.producer_stage_key === edge.producer_stage && artifact.output_name === edge.producer_output);
    if (edge.delivery === "producer_complete" ? !stageFinished(snapshot, edge.producer_stage) : !available && !stageFinished(snapshot, edge.producer_stage)) return false;
  }
  return true;
};

const shouldClose = (stage_key: StageKey, definition: CompiledWorkflowDefinition, snapshot: RunSnapshot): boolean =>
  definition.edges.filter((edge) => edge.consumer_stage === stage_key && edge.delivery === "unit_complete").every((edge) => stageFinished(snapshot, edge.producer_stage));

const selectInputsForUnit = (stage: CompiledStageContract, inputs: StageInputSet, unit: MaterializedExecutionUnit): StageInputSet => {
  if (stage.materialization.kind !== "fan_out") return inputs;
  const perUnit = new Set(stage.inputs.filter((input) => input.delivery === "unit_complete").map((input) => input.name));
  return Object.fromEntries(Object.entries(inputs).map(([name, value]) =>
    Array.isArray(value) && perUnit.has(name) ? [name, value.filter((artifact) => artifact.unit_id === unit.unit_id)] : [name, value]));
};

/** One per `contract.outputs` for fan_out/scalar; one per (item key × output), `collection_member`, for artifact_collection. */
const outputSlots = (contract: CompiledStageContract, unit: MaterializedExecutionUnit): Result<readonly MaterializedRunOutput[], { readonly path: string; readonly detail: string }> => {
  const materialization = contract.materialization;
  if (materialization.kind !== "artifact_collection") {
    return ok(contract.outputs.map((output) => ({ identity: { kind: "scalar" as const, output_name: output.name }, artifact_type: output.artifact_type, required: true, release: output.release })));
  }
  const outputs: MaterializedRunOutput[] = [];
  for (const item of unit.parameters as readonly JsonValue[]) {
    const key = readJsonPointer(item, materialization.id_path);
    if (typeof key !== "string" || key.length === 0) return err({ path: materialization.id_path, detail: `artifact collection key '${materialization.id_path}' must be a non-empty string` });
    for (const output of contract.outputs) outputs.push({ identity: { kind: "collection_member" as const, output_name: output.name, collection_key: key as OutputCollectionKey }, artifact_type: output.artifact_type, required: true, release: output.release });
  }
  return ok(outputs);
};

const selectDriverArtifacts = (inputs: StageInputSet, input_name: string): readonly ArtifactEnvelope[] => {
  const delivered = inputs[input_name];
  if (delivered === undefined) return [];
  return Array.isArray(delivered) ? delivered : [delivered as ArtifactEnvelope];
};

/** The `over.path` a binding carries, when it has one — "" otherwise. Used only to name a contradiction. */
const bindingPath = (binding: SlotBinding): string => ("path" in binding && typeof binding.path === "string" ? binding.path : "");

/** The artifact a binding is keyed on, when it names a single input envelope (or the first of a collected one). */
const sourceArtifactId = (binding: SlotBinding, inputs: StageInputSet): ArtifactId | null => {
  if (binding.from !== "input") return null;
  const value = inputs[binding.input_name];
  if (value === undefined) return null;
  const envelope = Array.isArray(value) ? value[0] : (value as ArtifactEnvelope);
  return envelope ? envelope.artifact_id : null;
};

const policyOf = (contract: CompiledStageContract): StagePolicy =>
  contract.materialization.kind === "fan_out"
    ? { max_parallel: contract.materialization.max_parallel, manual_admission: contract.materialization.manual_admission }
    : { max_parallel: 1, manual_admission: false };

interface DriverParseSpec { readonly unit_id_path: string; readonly depends_on_path: string | null }

/** Moved from `materialize-units.ts`'s `parseUnit`; returns the path that failed instead of throwing. */
const parseUnit = (item: JsonValue, spec: DriverParseSpec): Result<MaterializedExecutionUnit, { readonly path: string; readonly detail: string }> => {
  const id = readJsonPointer(item, spec.unit_id_path);
  if (typeof id !== "string" || id.length === 0) return err({ path: spec.unit_id_path, detail: `unit_id at '${spec.unit_id_path}' must be a non-empty string` });
  const dependsOnPath = spec.depends_on_path;
  const rawDependencies = dependsOnPath === null ? [] : readJsonPointer(item, dependsOnPath);
  if (!Array.isArray(rawDependencies) || rawDependencies.some((dependency) => typeof dependency !== "string" || dependency.length === 0))
    return err({ path: dependsOnPath ?? "", detail: "depends_on must be an array of non-empty strings" });
  const dependencies = rawDependencies as string[];
  if (dependencies.includes(id)) return err({ path: dependsOnPath ?? "", detail: "unit cannot depend on itself" });
  if (new Set(dependencies).size !== dependencies.length) return err({ path: dependsOnPath ?? "", detail: "unit repeats a dependency" });
  return ok({ unit_id: id as UnitId, parameters: item, depends_on: dependencies as UnitId[] });
};

interface MintedUnit {
  readonly unit_id: UnitId;
  readonly parameters: JsonValue;
  readonly depends_on: readonly UnitId[];
  readonly inputs: StageInputSet;
  readonly input_snapshot: readonly ArtifactEnvelope[];
  readonly input_fingerprint: InputFingerprint;
  readonly outputs: readonly MaterializedRunOutput[];
  readonly source_artifact_id: ArtifactId | null;
}

interface DriverUnit { readonly unit: MaterializedExecutionUnit; readonly source_artifact_id: ArtifactId | null }

const finalizeMintedUnits = (contract: CompiledStageContract, inputs: StageInputSet, driverUnits: readonly DriverUnit[]): Result<readonly MintedUnit[], Contradiction> => {
  const minted: MintedUnit[] = [];
  for (const { unit, source_artifact_id } of driverUnits) {
    const unitInputs = selectInputsForUnit(contract, inputs, unit);
    const input_snapshot = envelopes(unitInputs);
    const input_fingerprint = fingerprintOf(input_snapshot);
    const outputs = outputSlots(contract, unit);
    if (!outputs.ok) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: source_artifact_id, path: outputs.error.path, detail: outputs.error.detail });
    minted.push({ unit_id: unit.unit_id, parameters: unit.parameters, depends_on: unit.depends_on, inputs: unitInputs, input_snapshot, input_fingerprint, outputs: outputs.value, source_artifact_id });
  }
  return ok(minted);
};

/**
 * What a stage's units are, right now, from the persisted inputs alone.
 * `scalar` and `artifact_collection` always mint exactly unit `"0"`;
 * `fan_out` mints one unit per driver artifact (or per item of a
 * non-input `over` binding — repository provisioning fans out over run
 * context, which is why `malformed_driver_artifact.artifact_id` may be null).
 */
const mintUnits = (contract: CompiledStageContract, inputs: StageInputSet, context: JsonValue): Result<readonly MintedUnit[], Contradiction> => {
  const materialization = contract.materialization;
  const environment: BindingEnvironment = { inputs, context, item: null };

  if (materialization.kind === "scalar") return finalizeMintedUnits(contract, inputs, [{ unit: { unit_id: "0" as UnitId, parameters: {}, depends_on: [] }, source_artifact_id: null }]);

  if (materialization.kind === "artifact_collection") {
    const sourceId = sourceArtifactId(materialization.over, inputs);
    const path = bindingPath(materialization.over);
    const over = resolveBindingValue(materialization.over, environment);
    if (!over.ok) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: sourceId, path, detail: over.error.detail });
    if (!Array.isArray(over.value)) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: sourceId, path, detail: `${materialization.kind}.over must resolve to an array` });
    return finalizeMintedUnits(contract, inputs, [{ unit: { unit_id: "0" as UnitId, parameters: over.value, depends_on: [] }, source_artifact_id: sourceId }]);
  }

  // fan_out
  const spec: DriverParseSpec = { unit_id_path: materialization.unit_id_path, depends_on_path: materialization.depends_on_path };
  const driverUnits: DriverUnit[] = [];
  const seen = new Set<string>();

  if (materialization.over.from === "input") {
    for (const artifact of selectDriverArtifacts(inputs, materialization.over.input_name)) {
      const item = { unit_id: artifact.unit_id, artifact: artifact.body } as JsonValue;
      const parsed = parseUnit(item, spec);
      if (!parsed.ok) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: artifact.artifact_id, path: parsed.error.path, detail: parsed.error.detail });
      seen.add(parsed.value.unit_id);
      driverUnits.push({ unit: parsed.value, source_artifact_id: artifact.artifact_id });
    }
  } else {
    const over = resolveBindingValue(materialization.over, environment);
    if (!over.ok) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: null, path: bindingPath(materialization.over), detail: over.error.detail });
    if (!Array.isArray(over.value)) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: null, path: bindingPath(materialization.over), detail: `${materialization.kind}.over must resolve to an array` });
    for (const item of over.value) {
      const parsed = parseUnit(item, spec);
      if (!parsed.ok) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: null, path: parsed.error.path, detail: parsed.error.detail });
      if (seen.has(parsed.value.unit_id)) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: null, path: spec.unit_id_path, detail: `duplicate unit_id '${parsed.value.unit_id}'` });
      seen.add(parsed.value.unit_id);
      driverUnits.push({ unit: parsed.value, source_artifact_id: null });
    }
  }
  return finalizeMintedUnits(contract, inputs, driverUnits);
};

interface CycleNode { readonly unit_id: UnitId; readonly depends_on: readonly UnitId[] }

/** DFS as `appendIncrementalUnit` did, but returning the cycle path (e.g. `["a","b","a"]`) instead of a boolean. */
const findCycle = (nodes: readonly CycleNode[]): readonly UnitId[] | null => {
  const byId = new Map(nodes.map((node) => [node.unit_id, node]));
  const path: UnitId[] = [];
  const onPath = new Set<UnitId>();
  const visited = new Set<UnitId>();
  const visit = (id: UnitId): readonly UnitId[] | null => {
    if (onPath.has(id)) return [...path.slice(path.indexOf(id)), id];
    if (visited.has(id)) return null;
    onPath.add(id);
    path.push(id);
    for (const dependency of byId.get(id)?.depends_on ?? []) {
      if (byId.has(dependency)) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      }
    }
    path.pop();
    onPath.delete(id);
    visited.add(id);
    return null;
  };
  for (const node of [...nodes].sort((a, b) => byString(a.unit_id, b.unit_id))) {
    const cycle = visit(node.unit_id);
    if (cycle) return cycle;
  }
  return null;
};

const materializeUnitCommand = (run_id: WorkflowRunId, stage_key: StageKey, stage_instance_id: StageInstanceId, unit: MintedUnit, policy: StagePolicy): Command => ({
  kind: "materialize_unit", stage_key, stage_instance_id, run_unit_id: runUnitIdFor(run_id, stage_key, unit.unit_id), unit_id: unit.unit_id,
  parameters: unit.parameters, depends_on: unit.depends_on, inputs: unit.inputs, input_snapshot: unit.input_snapshot,
  input_fingerprint: unit.input_fingerprint, outputs: unit.outputs, policy,
});

const reviseUnitCommand = (stage_key: StageKey, stage_instance_id: StageInstanceId, existing: UnitSnapshot, unit: MintedUnit): Command => ({
  kind: "revise_unit", stage_key, stage_instance_id, run_unit_id: existing.id, unit_id: unit.unit_id,
  parameters: unit.parameters, inputs: unit.inputs, input_snapshot: unit.input_snapshot, input_fingerprint: unit.input_fingerprint,
});

// ---------------------------------------------------------------------------
// derive

export const derive = (snapshot: RunSnapshot): Result<Derivation, Contradiction> => {
  // A. Child outcome facts — any cancelled unit anywhere wins over any failed unit anywhere.
  const cancelledUnit = findFirstUnit(snapshot, (unit) => unit.state === "cancelled");
  if (cancelledUnit) return ok({ commands: [{ kind: "complete_run", outcome: cancelledUnit.outcome ?? { kind: "cancelled", reason: null } }] });
  const failedUnit = findFirstUnit(snapshot, (unit) => unit.state === "failed");
  if (failedUnit) return ok({ commands: [{ kind: "complete_run", outcome: failedUnit.outcome ?? { kind: "failed", code: "unit_failed", detail: failedUnit.unit_id } }] });

  const commands: Command[] = [];
  /** Stages this batch revises a unit of: their persisted "all satisfied" is about to stop being true. */
  const revisedStageIds = new Set<StageInstanceId>();
  const run_id = snapshot.run.id;
  const definition = snapshot.definition;

  // B. Materialization — definition stages, sorted stage_key order.
  for (const stage_key of Object.keys(definition.stages).sort(byString)) {
    const contract = definition.stages[stage_key]!;
    const stored: StageSnapshot | null = snapshot.stages.find((candidate) => candidate.stage_key === stage_key) ?? null;
    if (!isReady(stage_key, definition, snapshot)) continue;
    const inputs = stageInputs(stage_key, definition, snapshot);
    const stage_instance_id = stored?.id ?? stageInstanceIdFor(run_id, stage_key);

    // First mint for this stage: a cycle among the freshly minted units is refused
    // before anything is materialized — there is no stored stage yet to contradict later.
    if (!stored) {
      const minted = mintUnits(contract, inputs, snapshot.run.context);
      if (!minted.ok) return minted;
      const cycle = findCycle(minted.value.map((unit) => ({ unit_id: unit.unit_id, depends_on: unit.depends_on })));
      if (cycle) return err({ kind: "dependency_cycle", stage_key, cycle });
      commands.push({ kind: "materialize_stage", stage_key, stage_instance_id, policy: policyOf(contract) });
      for (const unit of minted.value) commands.push(materializeUnitCommand(run_id, stage_key, stage_instance_id, unit, policyOf(contract)));
      continue; // close / satisfy / start / succeed come on the next ask (recheck contract)
    }

    const minted = mintUnits(contract, inputs, snapshot.run.context);
    if (!minted.ok) return minted;

    // A revision (§1 rule 5) is applied whether or not the collection is
    // closed: closure fixes which units exist, not what their inputs are —
    // a released input revised later must relaunch its consumer (#458).
    // A unit that is new after closure has no command: the graph is closed,
    // and a producer that could still mint one is by definition not finished.
    let added = false;
    for (const unit of minted.value) {
      const existing = stored.units.find((candidate) => candidate.unit_id === unit.unit_id);
      if (existing) {
        if (existing.input_fingerprint !== unit.input_fingerprint) { commands.push(reviseUnitCommand(stage_key, stage_instance_id, existing, unit)); revisedStageIds.add(stage_instance_id); }
      }
      else if (!stored.materialization_closed) { commands.push(materializeUnitCommand(run_id, stage_key, stage_instance_id, unit, policyOf(contract))); added = true; }
    }
    if (stored.materialization_closed) continue;

    const nodes: CycleNode[] = stored.units.map((unit) => ({ unit_id: unit.unit_id, depends_on: unit.depends_on }));
    for (const unit of minted.value) if (!stored.units.some((candidate) => candidate.unit_id === unit.unit_id)) nodes.push({ unit_id: unit.unit_id, depends_on: unit.depends_on });
    const cycle = findCycle(nodes);
    if (cycle) return err({ kind: "dependency_cycle", stage_key, cycle });

    if (!added && shouldClose(stage_key, definition, snapshot)) {
      for (const unit of [...stored.units].sort((a, b) => byString(a.unit_id, b.unit_id))) {
        for (const dependency of unit.depends_on) {
          if (!stored.units.some((candidate) => candidate.unit_id === dependency)) return err({ kind: "unknown_dependency_at_close", stage_key, unit_id: unit.unit_id, dependency });
        }
      }
      commands.push({ kind: "close_materialization", stage_key, stage_instance_id, policy: policyOf(contract) });
    }
  }

  // C. Unit facts, starts, stage success — stored stages (a stored stage may have no definition entry: test fixtures).
  for (const stored of [...snapshot.stages].sort((a, b) => byString(a.stage_key, b.stage_key))) {
    if (stored.state !== "active") continue;
    const units = [...stored.units].sort((a, b) => byString(a.unit_id, b.unit_id));

    // A unit is discharged only by releasing its required outputs. `every`
    // over no slots is vacuously true, so a unit with none is never marked
    // satisfied here — it would complete without its executor ever running.
    // Definitions refuse a stage with no outputs; this is the local guard.
    const satisfiedNow = new Set<RunUnitId>();
    for (const unit of units) {
      if (!TERMINAL_UNIT_STATES.has(unit.state) && unit.required_slots.length > 0 && unit.required_slots.every((slot) => slot.state.kind === "released")) { commands.push({ kind: "mark_unit_satisfied", run_unit_id: unit.id }); satisfiedNow.add(unit.id); }
    }

    const running = units.filter((unit) => unit.work_orders.some((order) => order.state === "started") && unit.open_waits.length === 0).length;
    let capacity = stored.policy.max_parallel - running;

    for (const unit of units) {
      if (capacity <= 0) break;
      // A unit satisfied earlier in this same batch is not also started: `apply` already
      // guards `start_work_tx`, but an unguarded command here still burns a capacity slot.
      const eligible = !TERMINAL_UNIT_STATES.has(unit.state) && unit.open_waits.length === 0 && !unit.work_orders.some((order) => order.state === "started")
        && unit.admitted && unit.depends_on.every((dependency) => stored.units.find((candidate) => candidate.unit_id === dependency)?.state === "satisfied") && !satisfiedNow.has(unit.id);
      const order = unit.work_orders.filter((candidate) => candidate.state === "available")
        .sort((a, b) => (a.created_at === b.created_at ? byString(a.id, b.id) : byString(a.created_at, b.created_at)))[0];
      if (eligible && order) { commands.push({ kind: "start_work", work_order_id: order.id, run_unit_id: unit.id }); capacity -= 1; }
    }

    // Not for a stage this batch is revising a unit of: `revise_unit` resets that unit to
    // `ready`, and a stage marked succeeded here would never start it (§C skips non-active stages).
    if (stored.materialization_closed && !revisedStageIds.has(stored.id) && stored.units.every((unit) => unit.state === "satisfied")) commands.push({ kind: "mark_stage_succeeded", stage_instance_id: stored.id });
  }

  // D. Run completion — from persisted state only.
  const definitionStageKeys = Object.keys(definition.stages);
  if (snapshot.stages.length > 0 && definitionStageKeys.every((key) => snapshot.stages.some((stage) => stage.stage_key === key)) && snapshot.stages.every((stage) => stage.state === "succeeded")) {
    const outcome: StageOutcome = { kind: "succeeded" };
    commands.push({ kind: "complete_run", outcome });
  }

  return ok({ commands });
};

/**
 * The ids `derive` mints — spec §13, moved verbatim from
 * `runtime/run-materialization.ts`. Determinism here is what makes replay
 * and duplicate-ask safety free: never introduce a random id anywhere in
 * the decision path.
 */
import { createHash } from "node:crypto";

import type { InputFingerprint, RunUnitId, StageInstanceId, UnitId, WorkflowRunId, WorkOrderId } from "../domain/primitives";
import type { StageKey } from "../domain/workflow";

const stableUuid = (identity: string): string => {
  const hex = createHash("sha256").update(identity).digest("hex").slice(0, 32);
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-4${hex.slice(13, 16)}-8${hex.slice(17, 20)}-${hex.slice(20)}`;
};

export const stageInstanceIdFor = (run_id: WorkflowRunId, stage_key: StageKey): StageInstanceId =>
  stableUuid(`${run_id}:stage:${stage_key}`) as StageInstanceId;

export const runUnitIdFor = (run_id: WorkflowRunId, stage_key: StageKey, unit_id: UnitId): RunUnitId =>
  stableUuid(`${run_id}:${stage_key}:unit:${unit_id}`) as RunUnitId;

/** `identity` is `"initial"` or `"revision:<fingerprint>"`. */
export const workOrderIdFor = (run_id: WorkflowRunId, stage_key: StageKey, unit_id: UnitId, identity: string): WorkOrderId =>
  stableUuid(`${run_id}:${stage_key}:${unit_id}:${identity}`) as WorkOrderId;

export const workOrderWorkflowId = (work_order_id: WorkOrderId): string => `v2-work:${work_order_id}`;

export const fingerprintOf = (value: unknown): InputFingerprint => createHash("sha256").update(JSON.stringify(value)).digest("hex") as InputFingerprint;

/**
 * The pure decision layer's view of one run — everything `derive` needs to
 * compute the run's next commands, and nothing it does not. Loaded by
 * `load_run_snapshot` (storage layer, not this package) in one transaction
 * under `SELECT ... FOR UPDATE`.
 *
 * Amends spec §3.2: `released_artifacts` is dropped from `UnitSnapshot` —
 * nothing in `derive` needs a unit's own released artifacts, only the run's
 * `available_artifacts` (what downstream stages may consume).
 */
import type { CompiledWorkflowDefinition } from "../domain/compiled-workflow";
import type { ArtifactEnvelope } from "../domain/execution";
import type { InputFingerprint, JsonValue, RunUnitId, StageInstanceId, UnitId } from "../domain/primitives";
import type { RunOutputSlot, RunStage, UnitState, WorkflowRun, WorkOrder } from "../domain/run-record";
import type { Wait } from "../domain/wait";
import type { StageKey, StageOutcome } from "../domain/workflow";

export interface AvailableArtifact extends ArtifactEnvelope {
  readonly producer_stage_key: StageKey;
}

export interface StagePolicy {
  readonly max_parallel: number;
  readonly manual_admission: boolean;
}

export interface UnitSnapshot {
  readonly id: RunUnitId;
  readonly unit_id: UnitId;
  readonly parameters: JsonValue;
  readonly input_fingerprint: InputFingerprint;
  readonly state: UnitState;
  readonly admitted: boolean;
  /** Needed to propagate a failed/cancelled unit into a run outcome (spec §1 rule 6b/6c). */
  readonly outcome: StageOutcome | null;
  /** By unit_id; may name units with no row yet (an open collection's forward edge). */
  readonly depends_on: readonly UnitId[];
  /** Only slots with required=true. */
  readonly required_slots: readonly RunOutputSlot[];
  readonly open_waits: readonly Wait[];
  /** Every order of the unit, any state. */
  readonly work_orders: readonly WorkOrder[];
}

export interface StageSnapshot {
  readonly id: StageInstanceId;
  readonly stage_key: StageKey;
  readonly state: RunStage["state"];
  readonly materialization_closed: boolean;
  readonly policy: StagePolicy;
  readonly units: readonly UnitSnapshot[];
}

export interface RunSnapshot {
  readonly run: WorkflowRun;
  readonly definition: CompiledWorkflowDefinition;
  /** Only stages that have a stage_instance row. */
  readonly stages: readonly StageSnapshot[];
  readonly available_artifacts: readonly AvailableArtifact[];
}

import { expect, test } from "bun:test";

import { derive } from "../../src/decision/derive";
import type { Command } from "../../src/decision/commands";
import type { UnitId } from "../../src/domain/primitives";
import {
  PRODUCER_STAGE_KEY,
  availableBrief,
  emptyDefinition,
  fanOutDefinition,
  fingerprintForBrief,
  openWait,
  releasedSlot,
  emptySlot,
  runUnitIdForTest,
  scalarStageDefinition,
  snapshot,
  stage,
  unit,
  workOrder,
} from "./snapshot-builder";

// -----------------------------------------------------------------------
// 1. open collection, one unit with an unknown dependency → wait, no
//    contradiction, unit not started; then the dependency's unit arrives
//    with no row of its own → still wait.

test("case 1: an open collection materializes a unit whose dependency has no row yet, and starts nothing", () => {
  const definition = fanOutDefinition({ stage_key: "build", over_input: "brief", max_parallel: 2 });
  const rolloutBrief = availableBrief("rollout", ["versioning"]);
  const snap = snapshot({ definition, available_artifacts: [rolloutBrief], stages: [stage({ stage_key: "build", units: [] })] });

  const result = derive(snap);
  expect(result.ok).toBe(true);
  if (!result.ok) return;
  expect(result.value.commands).toEqual([
    { kind: "materialize_unit", stage_key: "build", stage_instance_id: snap.stages[0]!.id, run_unit_id: runUnitIdForTest("build", "rollout"),
      unit_id: "rollout" as UnitId, parameters: expect.anything(), depends_on: ["versioning" as UnitId], inputs: expect.anything(),
      input_snapshot: expect.anything(), input_fingerprint: expect.anything(), outputs: expect.anything(), policy: expect.anything() },
  ]);
  expect(result.value.commands.some((command) => command.kind === "start_work")).toBe(false);
});

test("case 1 continued: the dependent unit exists but its dependency has no row → wait", () => {
  const definition = fanOutDefinition({ stage_key: "build", over_input: "brief", max_parallel: 2 });
  const rolloutBrief = availableBrief("rollout", ["versioning"]);
  const snap = snapshot({
    definition, available_artifacts: [rolloutBrief],
    stages: [stage({ stage_key: "build", units: [
      unit({ stage_key: "build", unit_id: "rollout", state: "ready", depends_on: ["versioning"], input_fingerprint: fingerprintForBrief(rolloutBrief), work_orders: [workOrder({ state: "available" })] }),
    ] })],
  });

  const result = derive(snap);
  expect(result).toEqual({ ok: true, value: { commands: [] } });
});

// -----------------------------------------------------------------------
// 2. the missing dependency arrives and is satisfied → the dependent starts.

test("case 2: a satisfied dependency lets its dependent's available order start", () => {
  const definition = fanOutDefinition({ stage_key: "build", over_input: "brief", max_parallel: 2 });
  const rolloutBrief = availableBrief("rollout", ["versioning"]);
  const versioningBrief = availableBrief("versioning", []);
  const order = workOrder({ state: "available" });
  const snap = snapshot({
    definition, available_artifacts: [rolloutBrief, versioningBrief],
    stages: [stage({ stage_key: "build", max_parallel: 2, units: [
      unit({ stage_key: "build", unit_id: "versioning", state: "satisfied", input_fingerprint: fingerprintForBrief(versioningBrief), required_slots: [releasedSlot()] }),
      unit({ stage_key: "build", unit_id: "rollout", state: "ready", depends_on: ["versioning"], input_fingerprint: fingerprintForBrief(rolloutBrief), work_orders: [order] }),
    ] })],
  });

  const result = derive(snap);
  expect(result).toEqual({ ok: true, value: { commands: [{ kind: "start_work", work_order_id: order.id, run_unit_id: runUnitIdForTest("build", "rollout") }] } });
});

// -----------------------------------------------------------------------
// 3. close with an unresolved dependency → unknown_dependency_at_close.

test("case 3: closing with a dependency that names no unit is a contradiction", () => {
  const definition = fanOutDefinition({ stage_key: "build", over_input: "brief" });
  const producer = stage({ stage_key: PRODUCER_STAGE_KEY, materialization_closed: true, units: [unit({ stage_key: PRODUCER_STAGE_KEY, unit_id: "0", state: "satisfied", required_slots: [releasedSlot()] })] });
  const build = stage({ stage_key: "build", units: [unit({ stage_key: "build", unit_id: "b", depends_on: ["never"] })] });
  const snap = snapshot({ definition, available_artifacts: [], stages: [producer, build] });

  const result = derive(snap);
  expect(result).toEqual({ ok: false, error: { kind: "unknown_dependency_at_close", stage_key: "build", unit_id: "b" as UnitId, dependency: "never" as UnitId } });
});

// -----------------------------------------------------------------------
// 4. a cycle among known units, collection still open → dependency_cycle.

test("case 4: a cycle among already-known units is a contradiction, independent of closure", () => {
  const definition = fanOutDefinition({ stage_key: "build", over_input: "brief" });
  const driver = availableBrief("a", ["b"]); // keeps the stage "ready"; the cycle is proven from the stored units below
  const snap = snapshot({
    definition, available_artifacts: [driver],
    stages: [stage({ stage_key: "build", units: [
      unit({ stage_key: "build", unit_id: "a", depends_on: ["b"] }),
      unit({ stage_key: "build", unit_id: "b", depends_on: ["a"] }),
    ] })],
  });

  const result = derive(snap);
  expect(result.ok).toBe(false);
  if (result.ok) return;
  expect(result.error).toEqual({ kind: "dependency_cycle", stage_key: "build", cycle: ["a" as UnitId, "b" as UnitId, "a" as UnitId] });
});

test("case 4b: a cycle among first-minted units is a contradiction before anything is materialized", () => {
  const definition = fanOutDefinition({ stage_key: "build", over_input: "brief" });
  const aBrief = availableBrief("a", ["b"]);
  const bBrief = availableBrief("b", ["a"]);
  const snap = snapshot({ definition, available_artifacts: [aBrief, bBrief], stages: [] });

  const result = derive(snap);
  expect(result.ok).toBe(false);
  if (result.ok) return;
  expect(result.error).toEqual({ kind: "dependency_cycle", stage_key: "build", cycle: ["a" as UnitId, "b" as UnitId, "a" as UnitId] });
});

// -----------------------------------------------------------------------
// 5. capacity: four eligible, max_parallel=2 → two start_work, in unit_id order.

test("case 5: capacity admits only the two lowest unit_ids, in order", () => {
  const eligible = (unit_id: string) => unit({ stage_key: "build", unit_id, work_orders: [workOrder({ state: "available" })] });
  const snap = snapshot({
    stages: [stage({ stage_key: "build", max_parallel: 2, units: [eligible("alpha"), eligible("bravo"), eligible("charlie"), eligible("delta")] })],
  });

  const result = derive(snap);
  expect(result.ok).toBe(true);
  if (!result.ok) return;
  const started = result.value.commands.filter((command): command is Extract<Command, { kind: "start_work" }> => command.kind === "start_work");
  expect(started.map((command) => command.run_unit_id)).toEqual([runUnitIdForTest("build", "alpha"), runUnitIdForTest("build", "bravo")]);
});

// -----------------------------------------------------------------------
// 6. manual admission: eligible but unadmitted → wait.

test("case 6: manual admission withholds an otherwise-eligible unit until admitted", () => {
  const snap = snapshot({
    stages: [stage({ stage_key: "build", manual_admission: true, units: [
      unit({ stage_key: "build", unit_id: "u", admitted: false, work_orders: [workOrder({ state: "available" })] }),
    ] })],
  });

  const result = derive(snap);
  expect(result).toEqual({ ok: true, value: { commands: [] } });
});

// -----------------------------------------------------------------------
// 7. revision: same unit_id, new fingerprint → revise_unit, no new unit.

test("case 7: a driver artifact with a changed body revises the existing unit, not a new one", () => {
  const definition = fanOutDefinition({ stage_key: "build", over_input: "brief" });
  const revisedBrief = availableBrief("rollout", ["versioning"], undefined, { depends_on: ["versioning"], revision: 2 });
  const snap = snapshot({
    definition, available_artifacts: [revisedBrief],
    stages: [stage({ stage_key: "build", units: [unit({ stage_key: "build", unit_id: "rollout", depends_on: ["versioning"], input_fingerprint: "stale-fingerprint" })] })],
  });

  const result = derive(snap);
  expect(result.ok).toBe(true);
  if (!result.ok) return;
  expect(result.value.commands).toEqual([
    { kind: "revise_unit", stage_key: "build", stage_instance_id: snap.stages[0]!.id, run_unit_id: runUnitIdForTest("build", "rollout"),
      unit_id: "rollout" as UnitId, parameters: expect.anything(), inputs: expect.anything(), input_snapshot: expect.anything(), input_fingerprint: expect.anything() },
  ]);
});

test("case 7 continued: a closed collection still revises an existing unit, and never mints a new one", () => {
  const definition = fanOutDefinition({ stage_key: "build", over_input: "brief" });
  const revisedBrief = availableBrief("rollout", [], undefined, { depends_on: [], revision: 2 });
  const lateBrief = availableBrief("late", []);
  const snap = snapshot({
    definition, available_artifacts: [revisedBrief, lateBrief],
    stages: [stage({ stage_key: "build", materialization_closed: true,
      units: [unit({ stage_key: "build", unit_id: "rollout", input_fingerprint: "stale-fingerprint", state: "satisfied", required_slots: [releasedSlot()] })] })],
  });

  const result = derive(snap);
  expect(result.ok).toBe(true);
  if (!result.ok) return;
  // No `mark_stage_succeeded` alongside the revision: the batch resets the unit to `ready`,
  // and a stage succeeded in the same batch would never start the revised order.
  expect(result.value.commands.map((command) => command.kind)).toEqual(["revise_unit"]);
});

